cmd:
SP=<scratch>; mkdir -p $SP/vc/src && cd $SP/vc && cat > test.gpr <<'EOF'
project Test is
   for Source_Dirs use ("src");
   for Object_Dir use "obj";
end Test;
EOF
cat > src/tiny.ads <<'EOF'
package Tiny with SPARK_Mode is
   procedure P (K : Natural) with Ghost,
     Pre  => K <= 8,
     Post => 3 ** K >= 1;
end Tiny;
EOF
cat > src/tiny.adb <<'EOF'
package body Tiny with SPARK_Mode is
   procedure P (K : Natural) is null;
end Tiny;
EOF
gnatprove -P test.gpr --level=1 --debug -u tiny.adb 2>&1 | tail -20; echo "===="; find obj -name '*.smt2' | head
